import type { ImsHonoApp } from '@/app';
import {
    handleCreateSitePackage,
    handleCreateSitePackageRevision,
    handleListSitePackages,
    handlePublishSitePackageRevision,
    handleRotateSitePackagePreviewToken
} from '@/domains/site-packages/handlers/manage-site-packages';
import {
    handleGetPublicSitePackage,
    handleServePublishedSitePackageShell,
    handleServePreviewSitePackage,
    handleServePublishedSitePackage
} from '@/domains/site-packages/handlers/serve-site-package';
import {
    validatePreviewSitePackageParams,
    validatePublicSitePackageParams,
    validatePublishedSitePackageParams,
    validateSitePackageIdParams,
    validateSitePackageRevisionParams
} from '@/domains/site-packages/request';
import { coreAuth, coreCsrf, opOnly } from '@/middleware/hono-auth';
import { paramValidator } from '@/middleware/request-validation';

const sitePackageIdValidator = paramValidator(validateSitePackageIdParams);
const sitePackageRevisionValidator = paramValidator(validateSitePackageRevisionParams);
const publicSitePackageValidator = paramValidator(validatePublicSitePackageParams);
const publishedSitePackageValidator = paramValidator(validatePublishedSitePackageParams);
const previewSitePackageValidator = paramValidator(validatePreviewSitePackageParams);

export function registerSitePackageRoutes(app: ImsHonoApp): void {
    app.get(
        '/api/site-packages/:slug',
        publicSitePackageValidator,
        handleGetPublicSitePackage
    );
    app.get('/api/admin/site-packages', coreAuth, opOnly, handleListSitePackages);
    app.post(
        '/api/admin/site-packages',
        coreAuth,
        opOnly,
        coreCsrf,
        handleCreateSitePackage
    );
    app.post(
        '/api/admin/site-packages/:id/revisions',
        coreAuth,
        opOnly,
        coreCsrf,
        sitePackageIdValidator,
        handleCreateSitePackageRevision
    );
    app.post(
        '/api/admin/site-packages/:id/revisions/:revisionId/publish',
        coreAuth,
        opOnly,
        coreCsrf,
        sitePackageRevisionValidator,
        handlePublishSitePackageRevision
    );
    app.post(
        '/api/admin/site-packages/:id/revisions/:revisionId/preview-token',
        coreAuth,
        opOnly,
        coreCsrf,
        sitePackageRevisionValidator,
        handleRotateSitePackagePreviewToken
    );

    app.on(
        ['GET', 'HEAD'],
        '/sites/:slug',
        publicSitePackageValidator,
        handleServePublishedSitePackageShell
    );
    app.on(
        ['GET', 'HEAD'],
        '/sites/:slug/',
        publicSitePackageValidator,
        handleServePublishedSitePackageShell
    );
    app.on(
        ['GET', 'HEAD'],
        '/site-content/_preview/:previewToken',
        previewSitePackageValidator,
        handleServePreviewSitePackage
    );
    app.on(
        ['GET', 'HEAD'],
        '/site-content/_preview/:previewToken/*',
        previewSitePackageValidator,
        handleServePreviewSitePackage
    );
    app.on(
        ['GET', 'HEAD'],
        '/site-content/:slug/:revisionId',
        publishedSitePackageValidator,
        handleServePublishedSitePackage
    );
    app.on(
        ['GET', 'HEAD'],
        '/site-content/:slug/:revisionId/*',
        publishedSitePackageValidator,
        handleServePublishedSitePackage
    );
}
